using System;using System.IO;using System.Linq;using System.Reflection;using System.Collections.Generic;using UnityEngine;using UnityEditor;
[InitializeOnLoad]public static class BeachPalmLODFinish{const string D="Assets/Scenes/Oasis/SouthBeach/BeachDetails";static BeachPalmLODFinish(){EditorApplication.update+=Poll;}static void Poll(){if(EditorApplication.isCompiling||!File.Exists("BeachPalmLODFinish.request"))return;File.Delete("BeachPalmLODFinish.request");try{Run();}catch(Exception e){File.WriteAllText("FinalEnvironmentRoadReview/BeachPalmLODFinish.txt",e.ToString());}}
static void Run(){var root=PrefabUtility.LoadPrefabContents(D+"/Existing Curved City Palm.prefab");var lod=root.GetComponent<LODGroup>();var slots=lod.GetLODs();int nearCount=0,farCount=0;for(int j=0;j<slots[0].renderers.Length;j++){var f=slots[0].renderers[j].GetComponent<MeshFilter>();var data=typeof(FinalPNGCityDetails).GetMethod("Read",BindingFlags.Static|BindingFlags.NonPublic).Invoke(null,new object[]{f.sharedMesh});var type=data.GetType();var pp=(Vector3[])type.GetField("p").GetValue(data);var nn=(Vector3[])type.GetField("normal").GetValue(data);var uv=(Vector2[][])type.GetField("uv").GetValue(data);var cc=(Color[])type.GetField("colors").GetValue(data);var ii=(int[])type.GetField("ids").GetValue(data);nearCount+=ii.Length/3;var matrix=root.transform.worldToLocalMatrix*f.transform.localToWorldMatrix;var p=new List<Vector3>();var n=new List<Vector3>();var c=new List<Color>();var original=new List<int>();var map=new Dictionary<string,int>();var remap=new int[pp.Length];for(int i=0;i<pp.Length;i++){var v=matrix.MultiplyPoint3x4(pp[i]);var tex=uv[0]!=null?uv[0][i]:Vector2.zero;string key=Mathf.RoundToInt(v.x/.65f)+","+Mathf.RoundToInt(v.y/.65f)+","+Mathf.RoundToInt(v.z/.65f)+","+Mathf.RoundToInt(tex.x*4)+","+Mathf.RoundToInt(tex.y*4);int index;if(!map.TryGetValue(key,out index)){index=p.Count;map[key]=index;p.Add(v);n.Add(matrix.MultiplyVector(nn[i]).normalized);c.Add(cc!=null?cc[i]:Color.white);original.Add(i);}remap[i]=index;}var ids=new List<int>();for(int i=0;i<ii.Length;i+=3){int a=remap[ii[i]],b=remap[ii[i+1]],d=remap[ii[i+2]];if(a!=b&&b!=d&&a!=d&&Vector3.Cross(p[b]-p[a],p[d]-p[a]).sqrMagnitude>.000001f)ids.AddRange(new[]{a,b,d});}var mesh=new Mesh{name="Existing palm distant mobile "+j,indexFormat=UnityEngine.Rendering.IndexFormat.UInt16};mesh.SetVertices(p);mesh.SetNormals(n);mesh.SetColors(c);for(int u=0;u<8;u++)if(uv[u]!=null&&uv[u].Length==pp.Length)mesh.SetUVs(u,original.Select(i=>uv[u][i]).ToList());mesh.SetTriangles(ids,0);mesh.RecalculateBounds();mesh.RecalculateTangents();mesh.Optimize();AssetDatabase.CreateAsset(mesh,D+"/Palm mobile distant v3 "+j+".asset");slots[1].renderers[j].GetComponent<MeshFilter>().sharedMesh=mesh;farCount+=ids.Count/3;}lod.SetLODs(slots);lod.RecalculateBounds();PrefabUtility.SaveAsPrefabAsset(root,D+"/Existing Curved City Palm.prefab");PrefabUtility.UnloadPrefabContents(root);AssetDatabase.SaveAssets();File.WriteAllText("FinalEnvironmentRoadReview/BeachPalmLODFinish.txt","SUCCESS palm near triangles="+nearCount+"; far triangles="+farCount+"; original near mesh/materials preserved, UV/colors retained; lower-distance detail selected by LOD.");}}
